// ---------------------------------------------------------------------------------------------
// Node registry (persisted in NVS)
// ---------------------------------------------------------------------------------------------

mesp_node_t matter_nodes::s_nodes[MESP_MAX_NODES];
/** Tags an admin gave a node, comma-separated ("Living room,Kitchen"). Own NVS blob: the node blob keeps its layout. */
char matter_nodes::s_tags[MESP_MAX_NODES][64];
int64_t matter_nodes::s_last_seen[MESP_MAX_NODES]; // runtime only, esp_timer µs
/** Connection lost (mesp_matter_node_lost()) and no report since: its values aren't current. Runtime only. */
static bool s_offline[MESP_MAX_NODES];

/** Last known on/off, brightness and color temperature per endpoint (runtime only). Filled by read_node_state(). */
mesp_endpoint_state_t matter_nodes::s_state[MESP_MAX_NODES][MESP_MAX_EPS];

/** Last reported sensor values per endpoint (runtime only). Mostly from subscriptions (espm_subscriptions.cpp). */
mesp_measure_t matter_nodes::s_measure[MESP_MAX_NODES][MESP_MAX_EPS];

/** FeatureMap of the Switch cluster per endpoint (runtime only, 0 = unknown). From subscriptions. */
uint32_t matter_nodes::s_switch_features[MESP_MAX_NODES][MESP_MAX_EPS];

/** Last reported battery of a node (Power Source cluster, runtime only). */
mesp_battery_t matter_nodes::s_battery[MESP_MAX_NODES];

/** Last read power draw and energy total of a node (runtime only). */
mesp_power_t matter_nodes::s_power[MESP_MAX_NODES];

/** Features that keep something per node (mesp_matter_on_node_removed). */
#define MAX_REMOVED_LISTENERS 4
static void (*s_removed_listeners[MAX_REMOVED_LISTENERS])(uint64_t node_id);
/** Features that use the nodes' values (mesp_matter_on_values). */
#define MAX_VALUES_LISTENERS 4
static mesp_values_cb_t s_values_listeners[MAX_VALUES_LISTENERS];
size_t matter_nodes::s_node_count = 0;
static uint64_t s_next_node_id = 0x100;
SemaphoreHandle_t matter_nodes::s_mutex;

static void nodes_load()
{
    nvs_handle_t h;
    if (nvs_open("mesp_nodes", NVS_READONLY, &h) != ESP_OK) return;
    size_t len = sizeof(s_nodes);
    if (nvs_get_blob(h, "nodes", s_nodes, &len) == ESP_OK) {
        s_node_count = len / sizeof(mesp_node_t);
    }
    len = sizeof(s_tags);
    nvs_get_blob(h, "tags", s_tags, &len);
    nvs_get_u64(h, "next_id", &s_next_node_id);
    nvs_close(h);
    ESP_LOGI(TAG, "Loaded %u commissioned nodes", (unsigned)s_node_count);
}

void matter_nodes::nodes_save()
{
    nvs_handle_t h;
    if (nvs_open("mesp_nodes", NVS_READWRITE, &h) != ESP_OK) return;
    nvs_set_blob(h, "nodes", s_nodes, s_node_count * sizeof(mesp_node_t));
    nvs_set_blob(h, "tags", s_tags, s_node_count * sizeof(s_tags[0]));
    nvs_set_u64(h, "next_id", s_next_node_id);
    nvs_commit(h);
    nvs_close(h);
}

int matter_nodes::node_index(uint64_t node_id)
{
    for (size_t i = 0; i < s_node_count; i++) {
        if (s_nodes[i].node_id == node_id) return i;
    }
    return -1;
}

void matter_nodes::copy_str(char *dst, size_t dst_len, const char *src, size_t src_len)
{
    size_t n = src_len < dst_len - 1 ? src_len : dst_len - 1;
    memcpy(dst, src, n);
    dst[n] = '\0';
}

// ---------------------------------------------------------------------------------------------
// Reading basic information + descriptor of a node
// ---------------------------------------------------------------------------------------------

static int ep_slot(int idx, chip::EndpointId ep)
{
    for (uint8_t i = 0; i < s_nodes[idx].ep_count; i++) {
        if (s_nodes[idx].ep[i] == ep) return i;
    }
    return -1;
}

static mesp_endpoint_state_t *state_of(int idx, chip::EndpointId ep)
{
    int slot = ep_slot(idx, ep);
    return slot < 0 ? nullptr : &s_state[idx][slot];
}

/**
 * Tell the values listeners about the node: its values changed (`current`), or they're no longer
 * current. Not while it's offline: they may be outdated. Must hold the nodes lock.
 */
void matter_nodes::notify_values(int idx, bool current)
{
    if (current && s_offline[idx]) return;
    const mesp_node_t &node = s_nodes[idx];
    mesp_node_values v = {node.node_id, node.name, &s_battery[idx], &s_power[idx],
                          node.ep_count, node.ep,   s_measure[idx], s_state[idx]};
    for (auto cb : s_values_listeners)
        if (cb) cb(v, current);
}

static void store_attribute(int idx, const ConcreteDataAttributePath &path, chip::TLV::TLVReader *data)
{
    mesp_node_t &node = s_nodes[idx];
    chip::TLV::TLVReader reader;
    reader.Init(*data);

    if (path.mClusterId == PowerSource::Id) {
        mesp_battery_t &bat = s_battery[idx];
        if (path.mAttributeId == PowerSource::Attributes::BatPercentRemaining::Id) {
            chip::app::DataModel::Nullable<uint8_t> v;
            if (chip::app::DataModel::Decode(reader, v) != CHIP_NO_ERROR) return;
            bat.percent_x2 = v.IsNull() || v.Value() > 200 ? -1 : v.Value();
        } else if (path.mAttributeId == PowerSource::Attributes::BatChargeLevel::Id) {
            uint8_t v;
            if (chip::app::DataModel::Decode(reader, v) != CHIP_NO_ERROR) return;
            bat.level = v <= 2 ? v : -1;
        } else {
            return;
        }
        bat.updated = esp_timer_get_time();
        s_last_seen[idx] = bat.updated;
        return;
    }

    if (path.mClusterId == ElectricalPowerMeasurement::Id) {
        if (path.mAttributeId != ElectricalPowerMeasurement::Attributes::ActivePower::Id) return;
        chip::app::DataModel::Nullable<int64_t> v;
        if (chip::app::DataModel::Decode(reader, v) != CHIP_NO_ERROR || v.IsNull()) return;
        mesp_power_t &power = s_power[idx];
        power.mw = v.Value();
        power.ep = path.mEndpointId;
        power.updated = esp_timer_get_time();
        return;
    }

    if (path.mClusterId == ElectricalEnergyMeasurement::Id) {
        if (path.mAttributeId != ElectricalEnergyMeasurement::Attributes::CumulativeEnergyImported::Id) return;
        ElectricalEnergyMeasurement::Attributes::CumulativeEnergyImported::TypeInfo::DecodableType v;
        if (chip::app::DataModel::Decode(reader, v) != CHIP_NO_ERROR || v.IsNull()) return;
        s_power[idx].energy_mwh = v.Value().energy;
        s_power[idx].energy_updated = esp_timer_get_time();
        return;
    }

    if (path.mClusterId == TemperatureMeasurement::Id || path.mClusterId == RelativeHumidityMeasurement::Id) {
        int slot = ep_slot(idx, path.mEndpointId);
        if (slot < 0) return;
        mesp_measure_t &m = s_measure[idx][slot];
        int64_t now = esp_timer_get_time();
        // Null: the sensor has no valid reading right now – keep showing the last one with its age.
        if (path.mClusterId == TemperatureMeasurement::Id &&
            path.mAttributeId == TemperatureMeasurement::Attributes::MeasuredValue::Id) {
            chip::app::DataModel::Nullable<int16_t> v;
            if (chip::app::DataModel::Decode(reader, v) != CHIP_NO_ERROR || v.IsNull()) return;
            m.temp = v.Value();
            m.temp_at = now;
        } else if (path.mClusterId == RelativeHumidityMeasurement::Id &&
                   path.mAttributeId == RelativeHumidityMeasurement::Attributes::MeasuredValue::Id) {
            chip::app::DataModel::Nullable<uint16_t> v;
            if (chip::app::DataModel::Decode(reader, v) != CHIP_NO_ERROR || v.IsNull() || v.Value() > 10000) return;
            m.humidity = v.Value();
            m.humidity_at = now;
        } else {
            return;
        }
        s_last_seen[idx] = now;
        return;
    }

    if (path.mClusterId == Switch::Id) {
        int slot = ep_slot(idx, path.mEndpointId);
        uint32_t features;
        if (slot < 0 || path.mAttributeId != Switch::Attributes::FeatureMap::Id) return;
        if (chip::app::DataModel::Decode(reader, features) == CHIP_NO_ERROR) s_switch_features[idx][slot] = features;
        return;
    }

    if (path.mClusterId == OnOff::Id || path.mClusterId == LevelControl::Id || path.mClusterId == ColorControl::Id) {
        mesp_endpoint_state_t *state = state_of(idx, path.mEndpointId);
        if (!state) return;
        if (path.mClusterId == OnOff::Id && path.mAttributeId == OnOff::Attributes::OnOff::Id) {
            bool on;
            if (chip::app::DataModel::Decode(reader, on) == CHIP_NO_ERROR) state->on = on;
        } else if (path.mClusterId == LevelControl::Id &&
                   path.mAttributeId == LevelControl::Attributes::CurrentLevel::Id) {
            chip::app::DataModel::Nullable<uint8_t> level;
            if (chip::app::DataModel::Decode(reader, level) == CHIP_NO_ERROR && !level.IsNull()) {
                state->level = level.Value();
            }
        } else if (path.mClusterId == ColorControl::Id) {
            uint16_t v;
            if (chip::app::DataModel::Decode(reader, v) != CHIP_NO_ERROR) return;
            switch (path.mAttributeId) {
            case ColorControl::Attributes::ColorTemperatureMireds::Id: state->ct = v; break;
            case ColorControl::Attributes::ColorTempPhysicalMinMireds::Id: state->ct_min = v; break;
            case ColorControl::Attributes::ColorTempPhysicalMaxMireds::Id: state->ct_max = v; break;
            default: break;
            }
        }
        return;
    }

    if (path.mClusterId == BasicInformation::Id) {
        switch (path.mAttributeId) {
        case BasicInformation::Attributes::VendorName::Id: {
            chip::CharSpan s;
            if (chip::app::DataModel::Decode(reader, s) == CHIP_NO_ERROR) copy_str(node.vendor, sizeof(node.vendor), s.data(), s.size());
            break;
        }
        case BasicInformation::Attributes::ProductName::Id: {
            chip::CharSpan s;
            if (chip::app::DataModel::Decode(reader, s) == CHIP_NO_ERROR) copy_str(node.product, sizeof(node.product), s.data(), s.size());
            break;
        }
        case BasicInformation::Attributes::VendorID::Id: {
            uint16_t v;
            if (chip::app::DataModel::Decode(reader, v) == CHIP_NO_ERROR) node.vendor_id = v;
            break;
        }
        case BasicInformation::Attributes::ProductID::Id: {
            uint16_t v;
            if (chip::app::DataModel::Decode(reader, v) == CHIP_NO_ERROR) node.product_id = v;
            break;
        }
        default:
            break;
        }
    } else if (path.mClusterId == Descriptor::Id && path.mAttributeId == Descriptor::Attributes::DeviceTypeList::Id) {
        if (path.mEndpointId == 0) return; // root node
        chip::app::DataModel::DecodableList<Descriptor::Structs::DeviceTypeStruct::DecodableType> list;
        if (chip::app::DataModel::Decode(reader, list) != CHIP_NO_ERROR) return;
        auto it = list.begin();
        while (it.Next()) {
            uint32_t type = it.GetValue().deviceType;
            // Skip utility device types (bridged node, power source, electrical sensor, ...), keep the first
            // application type.
            if (type == 0x0013 || type == 0x0011 || type == 0x0012 || type == 0x0016 || type == 0x0510 ||
                type == 0x050d)
                continue;
            bool known = false;
            for (uint8_t i = 0; i < node.ep_count; i++) {
                if (node.ep[i] == path.mEndpointId) known = true;
            }
            if (!known && node.ep_count < MESP_MAX_EPS) {
                node.ep[node.ep_count] = path.mEndpointId;
                node.device_type[node.ep_count] = type;
                node.ep_count++;
            }
            break;
        }
    }
}

static void on_attribute(uint64_t node_id, const ConcreteDataAttributePath &path, chip::TLV::TLVReader *data)
{
    if (!data) return;
    NodesLock lock;
    int idx = node_index(node_id);
    if (idx < 0) return;
    s_offline[idx] = false; // it answered
    store_attribute(idx, path, data);
    notify_values(idx, true);
}

void mesp_matter_node_lost(uint64_t node_id)
{
    NodesLock lock;
    int idx = node_index(node_id);
    if (idx < 0 || s_offline[idx]) return;
    ESP_LOGI(TAG, "Node 0x%llx is offline", (unsigned long long)node_id);
    s_offline[idx] = true;
    notify_values(idx, false);
}

static void on_read_done(uint64_t node_id, const ScopedMemoryBufferWithSize<AttributePathParams> &,
                         const ScopedMemoryBufferWithSize<EventPathParams> &)
{
    NodesLock lock;
    int idx = node_index(node_id);
    if (idx < 0) return;
    s_last_seen[idx] = esp_timer_get_time();
    nodes_save();
    ESP_LOGI(TAG, "Node 0x%llx: %s %s", (unsigned long long)node_id, s_nodes[idx].vendor, s_nodes[idx].product);
    // Endpoints are known now: new switches get subscribed.
    mesp_matter_subscriptions_update();
}

/** Must be called with the CHIP stack lock held. */
esp_err_t matter_nodes::read_node_info(uint64_t node_id)
{
    {
        NodesLock lock;
        int idx = node_index(node_id);
        if (idx >= 0) s_nodes[idx].ep_count = 0;
    }
    ScopedMemoryBufferWithSize<AttributePathParams> attrs;
    ScopedMemoryBufferWithSize<EventPathParams> events;
    attrs.Alloc(7);
    if (!attrs.Get()) return ESP_ERR_NO_MEM;
    attrs[0] = AttributePathParams(0, BasicInformation::Id, BasicInformation::Attributes::VendorName::Id);
    attrs[1] = AttributePathParams(0, BasicInformation::Id, BasicInformation::Attributes::VendorID::Id);
    attrs[2] = AttributePathParams(0, BasicInformation::Id, BasicInformation::Attributes::ProductName::Id);
    attrs[3] = AttributePathParams(0, BasicInformation::Id, BasicInformation::Attributes::ProductID::Id);
    attrs[4] = AttributePathParams(Descriptor::Id, Descriptor::Attributes::DeviceTypeList::Id); // all endpoints
    // Wildcard endpoint: only battery-powered devices answer.
    attrs[5] = AttributePathParams(PowerSource::Id, PowerSource::Attributes::BatPercentRemaining::Id);
    attrs[6] = AttributePathParams(PowerSource::Id, PowerSource::Attributes::BatChargeLevel::Id);
    auto *cmd = chip::Platform::New<controller::read_command>(node_id, std::move(attrs), std::move(events),
                                                              on_attribute, on_read_done, nullptr);
    if (!cmd) return ESP_ERR_NO_MEM;
    return cmd->send_command();
}

// ---------------------------------------------------------------------------------------------
// Battery: read now and then (switches also report it through their subscription)
// ---------------------------------------------------------------------------------------------

/** One node per tick, round robin: with 32 nodes each one is read about once an hour. */
#define BATTERY_POLL_S 120
#define BATTERY_FIRST_POLL_S 30

static size_t s_battery_next = 0;

static void on_battery_read_done(uint64_t, const ScopedMemoryBufferWithSize<AttributePathParams> &,
                                 const ScopedMemoryBufferWithSize<EventPathParams> &)
{
}

/** Must hold the CHIP stack lock. */
static esp_err_t read_node_battery(uint64_t node_id)
{
    ScopedMemoryBufferWithSize<AttributePathParams> attrs;
    ScopedMemoryBufferWithSize<EventPathParams> events;
    attrs.Alloc(2);
    if (!attrs.Get()) return ESP_ERR_NO_MEM;
    attrs[0] = AttributePathParams(PowerSource::Id, PowerSource::Attributes::BatPercentRemaining::Id);
    attrs[1] = AttributePathParams(PowerSource::Id, PowerSource::Attributes::BatChargeLevel::Id);
    auto *cmd = chip::Platform::New<controller::read_command>(node_id, std::move(attrs), std::move(events),
                                                              on_attribute, on_battery_read_done, nullptr);
    if (!cmd) return ESP_ERR_NO_MEM;
    return cmd->send_command();
}

static void battery_poll_timer(chip::System::Layer *, void *)
{
    uint64_t node_id = 0;
    {
        NodesLock lock;
        if (s_node_count > 0) {
            s_battery_next %= s_node_count;
            node_id = s_nodes[s_battery_next++].node_id;
        }
    }
    if (node_id) read_node_battery(node_id); // timers run in the CHIP task with the stack lock held
    chip::DeviceLayer::SystemLayer().StartTimer(chip::System::Clock::Seconds32(BATTERY_POLL_S), battery_poll_timer,
                                                nullptr);
}

void mesp_matter_attribute_report(uint64_t node_id, const ConcreteDataAttributePath &path,
                                  chip::TLV::TLVReader *data)
{
    if (path.mClusterId == PowerSource::Id || path.mClusterId == TemperatureMeasurement::Id ||
        path.mClusterId == RelativeHumidityMeasurement::Id || path.mClusterId == OnOff::Id ||
        path.mClusterId == LevelControl::Id || path.mClusterId == ColorControl::Id || path.mClusterId == Switch::Id ||
        path.mClusterId == ElectricalPowerMeasurement::Id || path.mClusterId == ElectricalEnergyMeasurement::Id) {
        on_attribute(node_id, path, data);
    }
}

uint32_t mesp_matter_switch_features(uint64_t node_id, uint16_t ep)
{
    NodesLock lock;
    int idx = node_index(node_id);
    int slot = idx < 0 ? -1 : ep_slot(idx, ep);
    return slot < 0 ? 0 : s_switch_features[idx][slot];
}

// ---------------------------------------------------------------------------------------------
// Commissioning
// ---------------------------------------------------------------------------------------------

mesp_pair_t matter_nodes::s_pair;

// esp-matter reports nothing when the device is never found (discovery timeout before PASE), so
// the state would stay "running" forever and block new attempts. Give up on our own instead.
#define PAIR_DISCOVERY_TIMEOUT_S 45
#define PAIR_TOTAL_TIMEOUT_S 300

void matter_nodes::check_pair_timeout()
{
    if (s_pair.state != PAIR_RUNNING) return;
    int64_t elapsed = (esp_timer_get_time() - s_pair.started) / 1000000;
    if (!s_pair.pase_ok && elapsed > PAIR_DISCOVERY_TIMEOUT_S) {
        s_pair.state = PAIR_FAILED;
        strlcpy(s_pair.error,
                "Device not found. Check the setup code, put the device into pairing mode and keep it close "
                "to the hub.",
                sizeof(s_pair.error));
    } else if (elapsed > PAIR_TOTAL_TIMEOUT_S) {
        s_pair.state = PAIR_FAILED;
        strlcpy(s_pair.error, "Commissioning timed out", sizeof(s_pair.error));
    }
}

// Buffers handed to the commissioner must outlive the pairing call.
static char s_pair_payload[128];
static uint8_t s_pair_dataset[254];
/** The Thread network's dataset (mesp_matter_set_thread_dataset); none: no pairing over Thread. */
static mesp_thread_dataset_fn s_thread_dataset;
static char s_pair_ssid[33];
static char s_pair_pass[65];

static void on_pase(CHIP_ERROR err)
{
    ESP_LOGI(TAG, "PASE: %s", chip::ErrorStr(err));
    if (err == CHIP_NO_ERROR) {
        s_pair.pase_ok = true;
    } else {
        s_pair.state = PAIR_FAILED;
        snprintf(s_pair.error, sizeof(s_pair.error), "PASE session failed: %s", chip::ErrorStr(err));
    }
}

static void on_commissioning_success(chip::ScopedNodeId peer)
{
    ESP_LOGI(TAG, "Commissioned node 0x%llx", (unsigned long long)peer.GetNodeId());
    {
        NodesLock lock;
        if (s_node_count < MESP_MAX_NODES && node_index(peer.GetNodeId()) < 0) {
            mesp_node_t &node = s_nodes[s_node_count];
            memset(&node, 0, sizeof(node));
            node.node_id = peer.GetNodeId();
            copy_str(node.name, sizeof(node.name), s_pair.name, strlen(s_pair.name));
            node.network = s_pair.network;
            s_tags[s_node_count][0] = '\0';
            s_last_seen[s_node_count] = esp_timer_get_time();
            s_offline[s_node_count] = false;
            memset(s_state[s_node_count], 0xff, sizeof(s_state[s_node_count]));
            memset(s_measure[s_node_count], 0, sizeof(s_measure[s_node_count]));
            memset(s_switch_features[s_node_count], 0, sizeof(s_switch_features[s_node_count]));
            s_battery[s_node_count] = {-1, -1, 0};
            s_power[s_node_count] = {};
            s_node_count++;
            nodes_save();
        }
    }
    s_pair.state = PAIR_SUCCESS;
    read_node_info(peer.GetNodeId());
}

static void on_commissioning_failure(chip::ScopedNodeId peer, CHIP_ERROR error,
                                     chip::Controller::CommissioningStage stage,
                                     std::optional<chip::Credentials::AttestationVerificationResult> info)
{
    s_pair.state = PAIR_FAILED;
    snprintf(s_pair.error, sizeof(s_pair.error), "%s (stage: %s)", chip::ErrorStr(error),
             chip::Controller::StageToString(stage));
    ESP_LOGE(TAG, "Commissioning failed: %s", s_pair.error);
}

esp_err_t matter_nodes::start_pairing(const char *payload, const char *name, const char *network)
{
    check_pair_timeout();
    if (s_pair.state == PAIR_RUNNING) return ESP_ERR_INVALID_STATE;

    esp_matter::lock::ScopedChipStackLock chip_lock(portMAX_DELAY);
    // An attempt we gave up on (check_pair_timeout) is still registered with the commissioner, which
    // then refuses every new one with ESP_ERR_INVALID_STATE. Cancel it first.
    auto *commissioner = controller::matter_controller_client::get_instance().get_commissioner();
    if (commissioner->GetPairingDelegate() != nullptr) {
        ESP_LOGW(TAG, "Cancelling stale pairing of node 0x%llx", (unsigned long long)s_pair.node_id);
        commissioner->StopPairing(s_pair.node_id);
        commissioner->RegisterPairingDelegate(nullptr);
    }

    memset(&s_pair, 0, sizeof(s_pair));
    strlcpy(s_pair_payload, payload, sizeof(s_pair_payload));
    strlcpy(s_pair.name, name, sizeof(s_pair.name));
    {
        NodesLock lock;
        s_pair.node_id = s_next_node_id++;
        nodes_save();
    }

    controller::pairing_command::get_instance().set_callbacks({
        .pase_callback = on_pase,
        .commissioning_success_callback = on_commissioning_success,
        .commissioning_failure_callback = on_commissioning_failure,
    });

    esp_err_t err = ESP_ERR_NOT_SUPPORTED;
    if (strcmp(network, "thread") == 0) {
        uint8_t len = 0;
        if (!s_thread_dataset) {
            strlcpy(s_pair.error, "no Thread network on this hub", sizeof(s_pair.error));
            return ESP_ERR_NOT_SUPPORTED;
        }
        if (!s_thread_dataset(s_pair_dataset, &len)) {
            strlcpy(s_pair.error, "Thread network not formed yet", sizeof(s_pair.error));
            return ESP_ERR_INVALID_STATE;
        }
        s_pair.network = NET_THREAD;
        err = controller::pairing_code_thread(s_pair.node_id, s_pair_payload, s_pair_dataset, len);
    } else if (strcmp(network, "wifi") == 0) {
        wifi_config_t cfg;
        if (esp_wifi_get_config(WIFI_IF_STA, &cfg) != ESP_OK) return ESP_FAIL;
        strlcpy(s_pair_ssid, (const char *)cfg.sta.ssid, sizeof(s_pair_ssid));
        strlcpy(s_pair_pass, (const char *)cfg.sta.password, sizeof(s_pair_pass));
        s_pair.network = NET_WIFI;
        err = controller::pairing_code_wifi(s_pair.node_id, s_pair_ssid, s_pair_pass, s_pair_payload);
    } else {
        s_pair.network = NET_ONNETWORK;
        err = controller::pairing_code(s_pair.node_id, s_pair_payload);
    }
    if (err == ESP_OK) {
        s_pair.state = PAIR_RUNNING;
        s_pair.started = esp_timer_get_time();
    } else {
        s_pair.state = PAIR_FAILED;
        snprintf(s_pair.error, sizeof(s_pair.error), "failed to start pairing: %s", esp_err_to_name(err));
    }
    return err;
}

// ---------------------------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------------------------

void mesp_matter_set_thread_dataset(mesp_thread_dataset_fn get)
{
    s_thread_dataset = get;
}

template <class F, size_t N> static void add_listener(F (&slots)[N], F cb, const char *what)
{
    for (auto &slot : slots) {
        if (!slot) {
            slot = cb;
            return;
        }
    }
    ESP_LOGE(TAG, "Too many %s listeners", what);
}

void mesp_matter_on_values(mesp_values_cb_t cb)
{
    add_listener(s_values_listeners, cb, "values");
}

void mesp_matter_on_node_removed(void (*cb)(uint64_t node_id))
{
    add_listener(s_removed_listeners, cb, "node");
}

size_t mesp_matter_endpoints(mesp_endpoint_ref *out, size_t max)
{
    NodesLock lock;
    size_t n = 0;
    for (size_t i = 0; i < s_node_count; i++) {
        for (uint8_t e = 0; e < s_nodes[i].ep_count && n < max; e++) {
            out[n++] = {s_nodes[i].node_id, s_nodes[i].ep[e], s_nodes[i].device_type[e]};
        }
    }
    return n;
}

void mesp_matter_init()
{
    s_mutex = xSemaphoreCreateRecursiveMutex();
    memset(s_state, 0xff, sizeof(s_state)); // all unknown (-1)
    for (auto &bat : s_battery) bat = {-1, -1, 0};
    nodes_load();
}

void mesp_matter_start_controller()
{
    esp_matter::lock::ScopedChipStackLock lock(portMAX_DELAY);
    auto &client = controller::matter_controller_client::get_instance();
    client.init(MESP_CONTROLLER_NODE_ID, MESP_FABRIC_ID, 5580);
    client.setup_commissioner();
    ESP_LOGI(TAG, "Matter commissioner ready (fabric %d, node 0x%llx)", MESP_FABRIC_ID,
             (unsigned long long)MESP_CONTROLLER_NODE_ID);
    chip::DeviceLayer::SystemLayer().StartTimer(chip::System::Clock::Seconds32(BATTERY_FIRST_POLL_S),
                                                battery_poll_timer, nullptr);
}

static void on_state_read_done(uint64_t node_id, const ScopedMemoryBufferWithSize<AttributePathParams> &,
                               const ScopedMemoryBufferWithSize<EventPathParams> &)
{
    NodesLock lock;
    int idx = node_index(node_id);
    if (idx >= 0) s_last_seen[idx] = esp_timer_get_time();
}

/** Read on/off, brightness, color temperature, power, energy and sensor values of all endpoints. Must hold the CHIP stack lock. */
esp_err_t matter_nodes::read_node_state(uint64_t node_id)
{
    ScopedMemoryBufferWithSize<AttributePathParams> attrs;
    ScopedMemoryBufferWithSize<EventPathParams> events;
    attrs.Alloc(9);
    if (!attrs.Get()) return ESP_ERR_NO_MEM;
    // Wildcard endpoint: devices answer only for endpoints that have the cluster.
    attrs[0] = AttributePathParams(OnOff::Id, OnOff::Attributes::OnOff::Id);
    attrs[1] = AttributePathParams(LevelControl::Id, LevelControl::Attributes::CurrentLevel::Id);
    attrs[2] = AttributePathParams(ColorControl::Id, ColorControl::Attributes::ColorTemperatureMireds::Id);
    attrs[3] = AttributePathParams(ColorControl::Id, ColorControl::Attributes::ColorTempPhysicalMinMireds::Id);
    attrs[4] = AttributePathParams(ColorControl::Id, ColorControl::Attributes::ColorTempPhysicalMaxMireds::Id);
    attrs[5] = AttributePathParams(TemperatureMeasurement::Id, TemperatureMeasurement::Attributes::MeasuredValue::Id);
    attrs[6] = AttributePathParams(RelativeHumidityMeasurement::Id,
                                   RelativeHumidityMeasurement::Attributes::MeasuredValue::Id);
    attrs[7] = AttributePathParams(ElectricalPowerMeasurement::Id, ElectricalPowerMeasurement::Attributes::ActivePower::Id);
    attrs[8] = AttributePathParams(ElectricalEnergyMeasurement::Id,
                                   ElectricalEnergyMeasurement::Attributes::CumulativeEnergyImported::Id);
    auto *cmd = chip::Platform::New<controller::read_command>(node_id, std::move(attrs), std::move(events),
                                                              on_attribute, on_state_read_done, nullptr);
    if (!cmd) return ESP_ERR_NO_MEM;
    return cmd->send_command();
}

void matter_nodes::node_remove(int idx)
{
    NodesLock lock;
    const uint64_t node_id = s_nodes[idx].node_id;
    notify_values(idx, false);
    for (size_t i = idx; i + 1 < s_node_count; i++) {
        s_nodes[i] = s_nodes[i + 1];
        s_last_seen[i] = s_last_seen[i + 1];
        s_offline[i] = s_offline[i + 1];
        memcpy(s_state[i], s_state[i + 1], sizeof(s_state[i]));
        memcpy(s_measure[i], s_measure[i + 1], sizeof(s_measure[i]));
        memcpy(s_switch_features[i], s_switch_features[i + 1], sizeof(s_switch_features[i]));
        s_battery[i] = s_battery[i + 1];
        s_power[i] = s_power[i + 1];
        memcpy(s_tags[i], s_tags[i + 1], sizeof(s_tags[i]));
    }
    s_node_count--;
    nodes_save();
    mesp_matter_subscriptions_forget(node_id);
    for (auto cb : s_removed_listeners)
        if (cb) cb(node_id);
}
